  1541	    pub fn getContentScale(self: *Self) apprt.ContentScale {
  1542	        const priv = self.private();
  1543	        const widget = priv.render_surface.as(gtk.Widget);
  1544	
  1545	        const gtk_scale: f32 = scale: {
  1546	            const surface_scale = scale_util.widgetSurfaceScale(widget);
  1547	            if (surface_scale <= 0) {
  1548	                logWarnOnce("widget surface scale was non-positive: {d}", .{surface_scale});
  1549	                break :scale 1.0;
  1550	            }
  1551	            break :scale @floatCast(surface_scale);
  1552	        };
  1553	
  1554	        // Also scale using font-specific DPI, which is often exposed to the user
  1555	        // via DE accessibility settings (see https://docs.gtk.org/gtk4/class.Settings.html).
  1556	        const xft_dpi_scale = xft_scale: {
  1557	            // gtk-xft-dpi is font DPI multiplied by 1024. See
  1558	            // https://docs.gtk.org/gtk4/property.Settings.gtk-xft-dpi.html
  1559	            const gtk_xft_dpi = gsettings.get(.@"gtk-xft-dpi") orelse {
  1560	                logWarnOnce("gtk-xft-dpi was not set, using default value", .{});
  1561	                break :xft_scale 1.0;
  1562	            };
  1563	
  1564	            // Use a value of 1.0 for the XFT DPI scale if the setting is <= 0
  1565	            // See:
  1566	            // https://gitlab.gnome.org/GNOME/libadwaita/-/commit/a7738a4d269bfdf4d8d5429ca73ccdd9b2450421
  1567	            // https://gitlab.gnome.org/GNOME/libadwaita/-/commit/9759d3fd81129608dd78116001928f2aed974ead
  1568	            if (gtk_xft_dpi <= 0) {
  1569	                // -1 is a valid value which specifies default scale.
  1570	                // https://docs.gtk.org/gtk4/property.Settings.gtk-xft-dpi.html
  1571	                if (gtk_xft_dpi != -1) {
  1572	                    logWarnOnce("gtk-xft-dpi has invalid value ({}), using default", .{gtk_xft_dpi});
  1573	                }
  1574	                break :xft_scale 1.0;
  1575	            }
  1576	
  1577	            // As noted above gtk-xft-dpi is multiplied by 1024, so we divide by
  1578	            // 1024, then divide by the default value (96) to derive a scale. Note
  1579	            // gtk-xft-dpi can be fractional, so we use floating point math here.
  1580	            const xft_dpi: f32 = @as(f32, @floatFromInt(gtk_xft_dpi)) / 1024.0;
  1581	            break :xft_scale xft_dpi / 96.0;
  1582	        };
  1583	
  1584	        const scale = gtk_scale * xft_dpi_scale;
  1585	        return .{ .x = scale, .y = scale };
  1586	    }
