   499	    /// Find the next surface to focus when a node is being closed.
   500	    /// Goes to previous split unless we're the leftmost leaf, then goes to next.
   501	    private func findNextFocusTargetAfterClosing(node: SplitTree<Ghostty.SurfaceView>.Node) -> Ghostty.SurfaceView? {
   502	        guard let root = surfaceTree.root else { return nil }
   503	
   504	        // If we're the leftmost, then we move to the next surface after closing.
   505	        // Otherwise, we move to the previous.
   506	        if root.leftmostLeaf() == node.leftmostLeaf() {
   507	            return surfaceTree.focusTarget(for: .next, from: node)
   508	        } else {
   509	            return surfaceTree.focusTarget(for: .previous, from: node)
   510	        }
   511	    }
