 76	/// EGL_BAD_PARAMETER from eglGetPlatformDisplay means that no loaded
 77	/// EGL driver supports the surfaceless platform. Most often that is
 78	/// because no driver could be loaded at all, for example because the
 79	/// system's driver needs a newer libc than Ghostty was built against,
 80	/// so say which it is rather than leaving a bare error name.
 81	fn logUnsupportedPlatform() void {
 82	    // With no driver loaded, libglvnd reports no client extensions
 83	    // at all, since every platform comes from a driver.
 84	    const exts = egl.queryClientExtensions() orelse "";
 85	    if (exts.len == 0) {
 86	        log.err("no EGL driver could be loaded; check that a GPU driver " ++
 87	            "is installed and was built against a compatible libc " ++
 88	            "(LD_DEBUG=libs shows why a driver failed to load)", .{});
 89	        return;
 90	    }
 91	
 92	    if (!egl.hasExtension(exts, "EGL_MESA_platform_surfaceless")) {
 93	        log.err("the EGL driver does not support EGL_MESA_platform_surfaceless " ++
 94	            "client extensions={s}", .{exts});
 95	        return;
 96	    }
 97	
 98	    log.err("the EGL driver rejected the surfaceless platform; " ++
 99	        "client extensions={s}", .{exts});
100	}
