 141	    /// Wait for the process to end and return the exit status. This
 142	    /// can only be called ONCE. Once this returns, the state is reset.
 143	    pub fn wait(self: *FlatpakHostCommand) !u8 {
 144	        self.state_mutex.lockUncancelable(global.io());
 145	        defer self.state_mutex.unlock(global.io());
 146	
 147	        while (true) {
 148	            switch (self.state) {
 149	                .init => return Error.FlatpakMustBeStarted,
 150	                .err => return Error.FlatpakSpawnFail,
 151	                .started => {},
 152	                .exited => |v| {
 153	                    self.state = .{ .init = {} };
 154	                    self.state_cv.broadcast(global.io());
 155	                    return v.status;
 156	                },
 157	            }
 158	
 159	            self.state_cv.waitUncancelable(global.io(), &self.state_mutex);
 160	        }
